    34  type BaseReportActionContextMenuProps = {
    35      /** The ID of the report this report action is attached to. */
    36      reportID: string;
    37
    38      /** The ID of the report action this context menu is attached to. */
    39      reportActionID: string;
    40
    41      /** The ID of the original report from which the given reportAction is first created. */
    42      // originalReportID is used in withOnyx to get the reportActions for the original report
    43      // eslint-disable-next-line react/no-unused-prop-types
    44      originalReportID: string;
    45
    46      /**
    47       * If true, this component will be a small, row-oriented menu that displays icons but not text.
    48       * If false, this component will be a larger, column-oriented menu that displays icons alongside text in each row.
    49       */
    50      isMini?: boolean;
    51
    52      /** Controls the visibility of this component. */
    53      isVisible?: boolean;
    54
    55      /** The copy selection. */
    56      selection?: string;
    57
    58      /** Draft message - if this is set the comment is in 'edit' mode */
    59      draftMessage?: string;
    60
    61      /** String representing the context menu type [LINK, REPORT_ACTION] which controls context menu choices  */
    62      type?: ContextMenuType;
    63
    64      /** Target node which is the target of ContentMenu */
    65      anchor?: MutableRefObject<ContextMenuAnchor>;
    66
    67      /** Flag to check if the chat participant is Chronos */
    68      isChronosReport?: boolean;
    69
    70      /** Whether the provided report is an archived room */
    71      isArchivedRoom?: boolean;
    72
    73      /** Flag to check if the chat is pinned in the LHN. Used for the Pin/Unpin action */
    74      isPinnedChat?: boolean;
    75
    76      /** Flag to check if the chat is unread in the LHN. Used for the Mark as Read/Unread action */
    77      isUnreadChat?: boolean;
    78
    79      /**
    80       * Is the action a thread's parent reportAction viewed from within the thread report?
    81       * It will be false if we're viewing the same parent report action from the report it belongs to rather than the thread.
    82       */
    83      isThreadReportParentAction?: boolean;
    84
    85      /** Content Ref */
    86      contentRef?: RefObject<View>;
    87
    88      /** Function to check if context menu is active */
    89      checkIfContextMenuActive?: () => void;
    90
    91      /** List of disabled actions */
    92      disabledActions?: ContextMenuAction[];
    93
    94      /** Function to update emoji picker state */
    95      setIsEmojiPickerActive?: (state: boolean) => void;
    96  };
