   100  function BaseReportActionContextMenu({
   101      type = CONST.CONTEXT_MENU_TYPES.REPORT_ACTION,
   102      anchor,
   103      contentRef,
   104      isChronosReport = false,
   105      isArchivedRoom = false,
   106      isMini = false,
   107      isVisible = false,
   108      isPinnedChat = false,
   109      isUnreadChat = false,
   110      isThreadReportParentAction = false,
   111      selection = '',
   112      draftMessage = '',
   113      reportActionID,
   114      reportID,
   115      originalReportID,
   116      checkIfContextMenuActive,
   117      disabledActions = [],
   118      setIsEmojiPickerActive,
   119  }: BaseReportActionContextMenuProps) {
   120      const StyleUtils = useStyleUtils();
   121      const {translate} = useLocalize();
   122      // eslint-disable-next-line rulesdir/prefer-shouldUseNarrowLayout-instead-of-isSmallScreenWidth
   123      const {shouldUseNarrowLayout, isSmallScreenWidth} = useResponsiveLayout();
   124      const menuItemRefs = useRef<MenuItemRefs>({});
   125      const [shouldKeepOpen, setShouldKeepOpen] = useState(false);
   126      const wrapperStyle = StyleUtils.getReportActionContextMenuStyles(isMini, shouldUseNarrowLayout);
   127      const {isOffline} = useNetwork();
   128      const {isProduction} = useEnvironment();
   129      const threedotRef = useRef<View>(null);
   130      const [betas] = useOnyx(ONYXKEYS.BETAS);
   131      const [reportActions] = useOnyx(`${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${originalReportID}`, {
   132          canEvict: false,
   133      });
   134      const transactionID = ReportActionsUtils.getLinkedTransactionID(reportActionID, reportID);
   135      const [transaction] = useOnyx(`${ONYXKEYS.COLLECTION.TRANSACTION}${transactionID}`);
   136      const [user] = useOnyx(ONYXKEYS.USER);
   137      const policyID = ReportUtils.getReport(reportID)?.policyID;
   138      const workspaceAccountID = PolicyUtils.getWorkspaceAccountID(policyID ?? '-1');
   139      const [cardList = {}] = useOnyx(ONYXKEYS.CARD_LIST);
   140      const [cardsList] = useOnyx(`${ONYXKEYS.COLLECTION.WORKSPACE_CARDS_LIST}${workspaceAccountID}_${CONST.EXPENSIFY_CARD.BANK}`);
   141
   142      const reportAction: OnyxEntry<ReportAction> = useMemo(() => {
   143          if (isEmptyObject(reportActions) || reportActionID === '0' || reportActionID === '-1') {
   144              return;
   145          }
   146          return reportActions[reportActionID];
   147      }, [reportActions, reportActionID]);
   148
   149      const sourceID = ReportUtils.getSourceIDFromReportAction(reportAction);
   150
   151      const [download] = useOnyx(`${ONYXKEYS.COLLECTION.DOWNLOAD}${sourceID}`);
   152
   153      const childReport = ReportUtils.getReport(reportAction?.childReportID ?? '-1');
   154      const parentReportAction = ReportActionsUtils.getReportAction(childReport?.parentReportID ?? '', childReport?.parentReportActionID ?? '');
   155      const {reportActions: paginatedReportActions} = usePaginatedReportActions(childReport?.reportID ?? '-1');
   156
   157      const transactionThreadReportID = useMemo(
   158          () => ReportActionsUtils.getOneTransactionThreadReportID(childReport?.reportID ?? '-1', paginatedReportActions ?? [], isOffline),
   159          [childReport?.reportID, paginatedReportActions, isOffline],
   160      );
   161
   162      const [transactionThreadReport] = useOnyx(`${ONYXKEYS.COLLECTION.REPORT}${transactionThreadReportID}`);
   163
   164      const isMoneyRequestReport = useMemo(() => ReportUtils.isMoneyRequestReport(childReport), [childReport]);
   165      const isInvoiceReport = useMemo(() => ReportUtils.isInvoiceReport(childReport), [childReport]);
   166
   167      const requestParentReportAction = useMemo(() => {
   168          if (isMoneyRequestReport || isInvoiceReport) {
   169              if (!paginatedReportActions || !transactionThreadReport?.parentReportActionID) {
   170                  return undefined;
   171              }
   172              return paginatedReportActions.find((action) => action.reportActionID === transactionThreadReport.parentReportActionID);
   173          }
   174          return parentReportAction;
   175      }, [parentReportAction, isMoneyRequestReport, isInvoiceReport, paginatedReportActions, transactionThreadReport?.parentReportActionID]);
   176
   177      const moneyRequestAction = transactionThreadReportID ? requestParentReportAction : parentReportAction;
   178
   179      const [parentReportNameValuePairs] = useOnyx(`${ONYXKEYS.COLLECTION.REPORT_NAME_VALUE_PAIRS}${childReport?.parentReportID ?? '-1'}`);
   180      const parentReport = ReportUtils.getReport(childReport?.parentReportID ?? '-1');
   181
   182      const isMoneyRequest = useMemo(() => ReportUtils.isMoneyRequest(childReport), [childReport]);
   183      const isTrackExpenseReport = ReportUtils.isTrackExpenseReport(childReport);
   184      const isSingleTransactionView = isMoneyRequest || isTrackExpenseReport;
   185      const isMoneyRequestOrReport = isMoneyRequestReport || isSingleTransactionView;
   186
   187      const areHoldRequirementsMet =
   188          !isInvoiceReport && isMoneyRequestOrReport && !ReportUtils.isArchivedRoom(transactionThreadReportID ? childReport : parentReport, parentReportNameValuePairs);
   189
   190      const shouldEnableArrowNavigation = !isMini && (isVisible || shouldKeepOpen);
   191      let filteredContextMenuActions = ContextMenuActions.filter(
   192          (contextAction) =>
   193              !disabledActions.includes(contextAction) &&
   194              contextAction.shouldShow({
   195                  type,
   196                  reportAction,
   197                  isArchivedRoom,
   198                  betas,
   199                  menuTarget: anchor,
   200                  isChronosReport,

200                  isChronosReport,
   201                  reportID,
   202                  isPinnedChat,
   203                  isUnreadChat,
   204                  isThreadReportParentAction,
   205                  isOffline: !!isOffline,
   206                  isMini,
   207                  isProduction,
   208                  moneyRequestAction,
   209                  areHoldRequirementsMet,
   210                  user,
   211              }),
   212      );
   213
   214      if (isMini) {
   215          const menuAction = filteredContextMenuActions.at(-1);
   216          const otherActions = filteredContextMenuActions.slice(0, -1);
   217          if (otherActions.length > CONST.MINI_CONTEXT_MENU_MAX_ITEMS && menuAction) {
   218              filteredContextMenuActions = otherActions.slice(0, CONST.MINI_CONTEXT_MENU_MAX_ITEMS - 1);
   219              filteredContextMenuActions.push(menuAction);
   220          } else {
   221              filteredContextMenuActions = otherActions;
   222          }
   223      }
   224
   225      // Context menu actions that are not rendered as menu items are excluded from arrow navigation
   226      const nonMenuItemActionIndexes = filteredContextMenuActions.map((contextAction, index) =>
   227          'renderContent' in contextAction && typeof contextAction.renderContent === 'function' ? index : undefined,
   228      );
   229      const disabledIndexes = nonMenuItemActionIndexes.filter((index): index is number => index !== undefined);
   230
   231      const [focusedIndex, setFocusedIndex] = useArrowKeyFocusManager({
   232          initialFocusedIndex: -1,
   233          disabledIndexes,
   234          maxIndex: filteredContextMenuActions.length - 1,
   235          isActive: shouldEnableArrowNavigation,
   236      });
   237
   238      /**
   239       * Checks if user is anonymous. If true and the action doesn't accept for anonymous user, hides the context menu and
   240       * shows the sign in modal. Else, executes the callback.
   241       */
   242      const interceptAnonymousUser = (callback: () => void, isAnonymousAction = false) => {
   243          if (Session.isAnonymousUser() && !isAnonymousAction) {
   244              hideContextMenu(false);
   245
   246              InteractionManager.runAfterInteractions(() => {
   247                  Session.signOutAndRedirectToSignIn();
   248              });
   249          } else {
   250              callback();
   251          }
   252      };
   253
   254      useKeyboardShortcut(
   255          CONST.KEYBOARD_SHORTCUTS.ENTER,
   256          (event) => {
   257              if (!menuItemRefs.current[focusedIndex]) {
   258                  return;
   259              }
   260
   261              // Ensures the event does not cause side-effects beyond the context menu, e.g. when an outside element is focused
   262              if (event) {
   263                  event.stopPropagation();
   264              }
   265
   266              menuItemRefs.current[focusedIndex]?.triggerPressAndUpdateSuccess?.();
   267              setFocusedIndex(-1);
   268          },
   269          {isActive: shouldEnableArrowNavigation && shouldEnableContextMenuEnterShortcut, shouldPreventDefault: false},
   270      );
   271
   272      const openOverflowMenu = (event: GestureResponderEvent | MouseEvent, anchorRef: MutableRefObject<View | null>) => {
   273          showContextMenu(
   274              CONST.CONTEXT_MENU_TYPES.REPORT_ACTION,
   275              event,
   276              selection,
   277              anchorRef?.current as ViewType | RNText | null,
   278              reportID,
   279              reportAction?.reportActionID,
   280              originalReportID,
   281              draftMessage,
   282              checkIfContextMenuActive,
   283              () => {
   284                  checkIfContextMenuActive?.();
   285                  setShouldKeepOpen(false);
   286              },
   287              ReportUtils.isArchivedRoomWithID(originalReportID),
   288              ReportUtils.chatIncludesChronosWithID(originalReportID),
   289              undefined,
   290              undefined,
   291              filteredContextMenuActions,
   292              true,
   293              () => {},
   294              true,
   295              isThreadReportParentAction,
   296          );
   297      };
   298
   299      const cardIssuedActionOriginalMessage = ReportActionsUtils.isActionOfType(
   300          reportAction,
   301          CONST.REPORT.ACTIONS.TYPE.CARD_ISSUED,
   302          CONST.REPORT.ACTIONS.TYPE.CARD_ISSUED_VIRTUAL,
   303          CONST.REPORT.ACTIONS.TYPE.CARD_MISSING_ADDRESS,
   304      )
   305          ? ReportActionsUtils.getOriginalMessage(reportAction)
   306          : undefined;
   307      const cardID = cardIssuedActionOriginalMessage?.cardID ?? -1;
   308      const isPolicyAdmin = PolicyUtils.isPolicyAdmin(PolicyUtils.getPolicy(policyID));
   309      const card = isPolicyAdmin ? cardsList?.[cardID] : cardList[cardID];
   310
   311      return (
   312          (isVisible || shouldKeepOpen) && (
   313              <FocusTrapForModal active={!isMini && !isSmallScreenWidth}>
   314                  <View
   315                      ref={contentRef}
   316                      style={wrapperStyle}
   317                  >
   318                      {filteredContextMenuActions.map((contextAction, index) => {
   319                          const closePopup = !isMini;
   320                          const payload: ContextMenuActionPayload = {
   321                              // eslint-disable-next-line @typescript-eslint/non-nullable-type-assertion-style
   322                              reportAction: (reportAction ?? null) as ReportAction,
   323                              reportID,
   324                              draftMessage,
   325                              selection,
   326                              close: () => setShouldKeepOpen(false),
   327                              openContextMenu: () => setShouldKeepOpen(true),
   328                              interceptAnonymousUser,
   329                              openOverflowMenu,
   330                              setIsEmojiPickerActive,
   331                              moneyRequestAction,
   332                              hasCard: !!card,
   333                          };
   334
   335                          if ('renderContent' in contextAction) {
   336                              return contextAction.renderContent(closePopup, payload);
   337                          }
   338
   339                          const {textTranslateKey} = contextAction;
   340                          const isKeyInActionUpdateKeys =
   341                              textTranslateKey === 'reportActionContextMenu.editAction' ||
   342                              textTranslateKey === 'reportActionContextMenu.deleteAction' ||
   343                              textTranslateKey === 'reportActionContextMenu.deleteConfirmation';
   344                          const text = textTranslateKey && (isKeyInActionUpdateKeys ? translate(textTranslateKey, {action: reportAction}) : translate(textTranslateKey));
   345                          const transactionPayload = textTranslateKey === 'reportActionContextMenu.copyToClipboard' && transaction && {transaction};
   346                          const isMenuAction = textTranslateKey === 'reportActionContextMenu.menu';
   347
   348                          return (
   349                              <ContextMenuItem
   350                                  ref={(ref) => {
   351                                      menuItemRefs.current[index] = ref;
   352                                  }}
   353                                  buttonRef={isMenuAction ? threedotRef : {current: null}}
   354                                  icon={contextAction.icon}
   355                                  text={text ?? ''}
   356                                  successIcon={contextAction.successIcon}
   357                                  successText={contextAction.successTextTranslateKey ? translate(contextAction.successTextTranslateKey) : undefined}
   358                                  isMini={isMini}
   359                                  key={contextAction.textTranslateKey}
   360                                  onPress={(event) =>
   361                                      interceptAnonymousUser(
   362                                          () => contextAction.onPress?.(closePopup, {...payload, ...transactionPayload, event, ...(isMenuAction ? {anchorRef: threedotRef} : {})}),
   363                                          contextAction.isAnonymousAction,
   364                                      )
   365                                  }
   366                                  description={contextAction.getDescription?.(selection) ?? ''}
   367                                  isAnonymousAction={contextAction.isAnonymousAction}
   368                                  isFocused={focusedIndex === index}
   369                                  shouldPreventDefaultFocusOnPress={contextAction.shouldPreventDefaultFocusOnPress}
   370                                  onFocus={() => setFocusedIndex(index)}
   371                                  onBlur={() => (index === filteredContextMenuActions.length - 1 || index === 1) && setFocusedIndex(-1)}
   372                                  disabled={contextAction?.shouldDisable ? contextAction?.shouldDisable(download) : false}
   373                                  shouldShowLoadingSpinnerIcon={contextAction?.shouldDisable ? contextAction?.shouldDisable(download) : false}
   374                              />
   375                          );
   376                      })}
   377                  </View>
   378              </FocusTrapForModal>
   379          )
   380      );
   381  }
   382
   383  export default memo(BaseReportActionContextMenu, lodashIsEqual);
