    57  /**
    58   * Hide the ReportActionContextMenu modal popover.
    59   * Hides the popover menu with an optional delay
    60   * @param [shouldDelay] - whether the menu should close after a delay
    61   * @param [onHideCallback] - Callback to be called after Context Menu is completely hidden
    62   */
    63  function hideContextMenu(shouldDelay?: boolean, onHideCallback = () => {}) {
    64      if (!contextMenuRef.current) {
    65          return;
    66      }
    67      if (!shouldDelay) {
    68          contextMenuRef.current.hideContextMenu(onHideCallback);
    69          return;
    70      }
    71
    72      // Save the active instanceID for which hide action was called.
    73      // If menu is being closed with a delay, check that whether the same instance exists or a new was created.
    74      // If instance is not same, cancel the hide action
    75      const instanceID = contextMenuRef.current.instanceID;
    76      setTimeout(() => {
    77          if (contextMenuRef.current?.instanceID !== instanceID) {
    78              return;
    79          }
    80
    81          contextMenuRef.current.hideContextMenu(onHideCallback);
    82      }, 800);
    83  }
