    85  /**
    86   * Show the ReportActionContextMenu modal popover.
    87   *
    88   * @param type - the context menu type to display [EMAIL, LINK, REPORT_ACTION, REPORT]
    89   * @param [event] - A press event.
    90   * @param [selection] - Copied content.
    91   * @param contextMenuAnchor - popoverAnchor
    92   * @param reportID - Active Report Id
    93   * @param reportActionID - ReportActionID for ContextMenu
    94   * @param originalReportID - The currrent Report Id of the reportAction
    95   * @param draftMessage - ReportAction Draftmessage
    96   * @param [onShow=() => {}] - Run a callback when Menu is shown
    97   * @param [onHide=() => {}] - Run a callback when Menu is hidden
    98   * @param isArchivedRoom - Whether the provided report is an archived room
    99   * @param isChronosReport - Flag to check if the chat participant is Chronos
   100   * @param isPinnedChat - Flag to check if the chat is pinned in the LHN. Used for the Pin/Unpin action
   101   * @param isUnreadChat - Flag to check if the chat has unread messages in the LHN. Used for the Mark as Read/Unread action
   102   */
   103  function showContextMenu(
   104      type: ContextMenuType,
   105      event: GestureResponderEvent | MouseEvent,
   106      selection: string,
   107      contextMenuAnchor: ContextMenuAnchor,
   108      reportID = '-1',
   109      reportActionID = '-1',
   110      originalReportID = '-1',
   111      draftMessage: string | undefined = undefined,
   112      onShow = () => {},
   113      onHide = () => {},
   114      isArchivedRoom = false,
   115      isChronosReport = false,
   116      isPinnedChat = false,
   117      isUnreadChat = false,
   118      disabledActions: ContextMenuAction[] = [],
   119      shouldCloseOnTarget = false,
   120      setIsEmojiPickerActive = () => {},
   121      isOverflowMenu = false,
   122      isThreadReportParentAction = false,
   123  ) {
   124      if (!contextMenuRef.current) {
   125          return;
   126      }
   127      const show = () => {
   128          contextMenuRef.current?.showContextMenu(
   129              type,
   130              event,
   131              selection,
   132              contextMenuAnchor,
   133              reportID,
   134              reportActionID,
   135              originalReportID,
   136              draftMessage,
   137              onShow,
   138              onHide,
   139              isArchivedRoom,
   140              isChronosReport,
   141              isPinnedChat,
   142              isUnreadChat,
   143              disabledActions,
   144              shouldCloseOnTarget,
   145              setIsEmojiPickerActive,
   146              isOverflowMenu,
   147              isThreadReportParentAction,
   148          );
   149      };
   150
   151      // If there is an already open context menu, close it first before opening
   152      // a new one.
   153      if (contextMenuRef.current.instanceID) {
   154          hideContextMenu(false, show);
   155          return;
   156      }
   157
   158      show();
   159  }
